// 取得 HN 故事內容
const storyIds = $input.first().json;
const items = [];

for (let i = 0; i < Math.min(storyIds.length, 15); i++) {
  const id = storyIds[i];
  const url = `https://hacker-news.firebaseio.com/v0/item/${id}.json`;
  items.push({url, id});
}

return items.map(item => ({json: {url: item.url}}));

