// 合併 GitHub Trending + HN 結果
const githubData = $('GitHub Trending').all()[0].json;
const hnData = $('LLM 摘要處理').all();

const githubNews = (Array.isArray(githubData) ? githubData : githubData.repos || [])
  .slice(0, 10)
  .map(r => ({
    title: r.name,
    summary: r.description || '無描述',
    url: r.url || r.html_url,
    source: 'GitHub',
    score: Math.min(Math.floor((r.stars || 0) / 100), 10),
    tags: (r.language ? [r.language] : []).concat(['開源', '熱門'])
  }));

const hnNews = hnData.map(d => d.json).filter(j => j && j.title);

return [{json: {news: [...githubNews, ...hnNews]}}];

// 統計熱門關鍵詞
const newsData = $input.first().json.news;
const keywordCount = {};

newsData.forEach(item => {
  const words = (item.title + ' ' + item.summary).split(/[\s\-,;:]/);
  words.forEach(w => {
    if (w.length > 3 && !['https', 'http', 'github', 'com'].includes(w.toLowerCase())) {
      keywordCount[w] = (keywordCount[w] || 0) + 1;
    }
  });
});

const topKeywords = Object.entries(keywordCount)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([word, count]) => ({word, count}));

return [{json: {trending: topKeywords}}];
